import { describe, expect, it } from 'vitest';
import Printer from '../../printer/Printer';
import { buildPrusaConfig, formatPrusaIni, parsePrusaGcode } from './prusaGcode';
import { DEFAULT_REGULAR_CONFIG } from './regularSlicer';

// Shaped like PrusaSlicer's own output with relative E: a layer change, a retract/unretract around
// a travel, a fan change, a wipe and temperature/progress lines that belong to our emitter.
const SAMPLE = `
; generated by PrusaSlicer
M73 P0 R2
M104 S215
M83 ; use relative distances for extrusion
G92 E0
;LAYER_CHANGE
;Z:0.2
G1 Z.2 F720
G1 X10 Y10 F9000
G1 E.8 F2100
;TYPE:External perimeter
G1 F1800
G1 X20 Y10 E.5
G1 X20 Y20 E.5
M106 S255
;WIPE_START
G1 X15 Y20 E-.3
;WIPE_END
G1 E-.5 F2100
G1 X30 Y30 F9000
G1 E.8 F2100
;TYPE:Solid infill
G1 X31 Y30 E.05 F1500
M73 P100 R0
G1 E-.8 F2100
`;

describe('parsePrusaGcode', () => {
    const path = parsePrusaGcode(SAMPLE, { extruder: 1 });

    it('keeps every move once x, y and z are known, starting with a travel', () => {
        expect(path.map(p => [p.point.x, p.point.y, p.point.z])).toEqual([
            [10, 10, 0.2], [20, 10, 0.2], [20, 20, 0.2], [15, 20, 0.2], [30, 30, 0.2], [31, 30, 0.2],
        ]);
        expect(path[0].travel).toBe(true);
        expect(path[0].extruder).toBe(1);
        expect(path.slice(1).every(p => p.extruder === undefined)).toBe(true);
    });

    it('copies the exact extrusion and the modal feed rate of each move', () => {
        expect(path[1]).toMatchObject({ regularSegment: true, extrusion: 0.5, speed: 1800 });
        expect(path[5]).toMatchObject({ regularSegment: true, extrusion: 0.05, speed: 1500 });
    });

    it('keeps a wipe as a travel that retracts', () => {
        expect(path[3]).toMatchObject({ travel: true, extrusion: -0.3 });
        expect(path[3].regularSegment).toBeUndefined();
    });

    it('puts retractions and fan changes before the next move, and drops the final retraction', () => {
        expect(path[1].preGcode).toEqual(['G1 E0.8 F2100']);
        expect(path[3].preGcode).toEqual(['M106 S255']);
        expect(path[4].preGcode).toEqual(['G1 E-0.5 F2100']);
        expect(path[5].preGcode).toEqual(['G1 E0.8 F2100']);
        expect(path.flatMap(p => p.preGcode ?? []).some(line => /M10[49]|M73/.test(line))).toBe(false);
    });

    it('labels feature changes', () => {
        expect(path[1].debug).toBe('PrusaSlicer: External perimeter');
        expect(path[5].debug).toBe('PrusaSlicer: Solid infill');
    });

    it('keeps the filament balance: retractions and unretractions are carried over in full', () => {
        const total = path.reduce((sum, p) =>
            sum + (p.extrusion ?? 0) + (p.preGcode ?? []).reduce((s, line) => s + Number(/E(-?[\d.]+)/.exec(line)?.[1] ?? 0), 0), 0);
        // Everything in the sample except the final, dropped retraction.
        expect(total).toBeCloseTo(0.8 + 0.5 + 0.5 - 0.3 - 0.5 + 0.8 + 0.05, 9);
    });

    it('returns nothing when nothing is extruded', () => {
        expect(parsePrusaGcode('G1 Z.2\nG1 X1 Y1\n', { extruder: 0 })).toEqual([]);
    });

    it('refuses G-code it cannot reproduce', () => {
        expect(() => parsePrusaGcode('M82\n', { extruder: 0 })).toThrow(/absolute extrusion/);
        expect(() => parsePrusaGcode('G1 Z1\nG1 X1 Y1\nG2 X2 Y2 I1 J0 E.1\n', { extruder: 0 })).toThrow(/arcs/);
        expect(() => parsePrusaGcode('G92 X0 Y0\n', { extruder: 0 })).toThrow(/resets the head/);
    });
});

describe('buildPrusaConfig', () => {
    it('maps the part settings and forces the settings the parser relies on', () => {
        const printer = new Printer();
        const config = buildPrusaConfig(printer, { ...DEFAULT_REGULAR_CONFIG, infillDensity: 35, printSpeed: 3000 });
        expect(config).toMatchObject({
            use_relative_e_distances: '1',
            arc_fitting: 'disabled',
            start_gcode: '',
            fill_density: '35%',
            perimeters: String(DEFAULT_REGULAR_CONFIG.perimeters),
            layer_height: String(DEFAULT_REGULAR_CONFIG.layerHeight),
            perimeter_speed: '50.00',
            bed_shape: `0x0,${printer.machine_depth}x0,${printer.machine_depth}x${printer.machine_depth_y},0x${printer.machine_depth_y}`,
        });
    });

    it('rejects an extruder that does not exist', () => {
        expect(() => buildPrusaConfig(new Printer(), { ...DEFAULT_REGULAR_CONFIG, extruder: 9 })).toThrow(/Extruder 9/);
    });
});

describe('formatPrusaIni', () => {
    it('writes key = value lines', () => {
        expect(formatPrusaIni({ perimeters: '2', start_gcode: '' })).toBe('perimeters = 2\nstart_gcode = \n');
    });

    it('refuses values that would start a new setting', () => {
        expect(() => formatPrusaIni({ start_gcode: 'G28\nM104' })).toThrow(/line break/);
        expect(() => formatPrusaIni({ 'bad key': '1' })).toThrow(/not a valid/);
    });
});

describe('emitting parsed PrusaSlicer moves', () => {
    it('copies extrusion amounts, feed rates and pre-move lines into the G-code', () => {
        const printer = new Printer();
        const gcode = printer.generate_foam_gcode(parsePrusaGcode(SAMPLE, { extruder: 0 }), printer.createEmitterState(0));
        const lines = gcode.split('\n');
        expect(lines).toContain('G0 X10.000000 Y10.000000 Z0.200000 F9000');
        expect(lines).toContain('G1 E0.8 F2100');
        expect(lines).toContain('G1 X20.000000 Y10.000000 Z0.200000 E0.500000 F1800');
        expect(lines).toContain('G1 X15.000000 Y20.000000 Z0.200000 E-0.300000 F1800');
        expect(lines).toContain('M106 S255');
        // The fan change comes right before the wipe it was in front of.
        expect(lines.indexOf('M106 S255')).toBe(lines.indexOf('G1 X15.000000 Y20.000000 Z0.200000 E-0.300000 F1800') - 1);
    });
});
